-- SQL131 SOURCE PROPOSAL. Root is sole canonical writer/registrar.
-- Candidate-only one-to-one extension of original execution, never another Run,
-- queue, scheduler, credential issuer, image approval or readiness authority.
-- No legacy row is adopted/backfilled; production data/credential guards untouched.
ALTER TABLE job_run_managed_execution ADD COLUMN candidate_waiting_protocol TEXT
 CHECK(candidate_waiting_protocol IS NULL OR (purpose='candidate-inert-v1' AND candidate_waiting_protocol='original-candidate-waiting-v1'));
CREATE TABLE managed_candidate_lifecycle_schema(singleton INTEGER PRIMARY KEY CHECK(singleton=1),schema_version INTEGER NOT NULL CHECK(schema_version=1));
INSERT INTO managed_candidate_lifecycle_schema VALUES(1,1);
CREATE TRIGGER candidate131_schema_no_update BEFORE UPDATE ON managed_candidate_lifecycle_schema BEGIN SELECT RAISE(ABORT,'Candidate lifecycle schema is immutable'); END;
CREATE TRIGGER candidate131_schema_no_delete BEFORE DELETE ON managed_candidate_lifecycle_schema BEGIN SELECT RAISE(ABORT,'Candidate lifecycle schema is retained'); END;
CREATE TRIGGER candidate131_schema_no_replace BEFORE INSERT ON managed_candidate_lifecycle_schema WHEN EXISTS(SELECT 1 FROM managed_candidate_lifecycle_schema WHERE singleton=NEW.singleton) BEGIN SELECT RAISE(ABORT,'Candidate lifecycle schema cannot be replaced'); END;
CREATE TABLE job_run_candidate_lifecycle (
 run_id TEXT PRIMARY KEY REFERENCES job_run_managed_execution(run_id) ON DELETE RESTRICT,
 attempt_id TEXT NOT NULL UNIQUE,
 candidate_intent_hash TEXT NOT NULL UNIQUE,
 spec_hash TEXT NOT NULL,
 run_identity_hash TEXT NOT NULL,
 selection_sha256 TEXT NOT NULL,
 organization_id TEXT NOT NULL,
 owner_user_id TEXT NOT NULL,
 project_id TEXT NOT NULL,
 job_id TEXT NOT NULL,
 runtime_id TEXT NOT NULL,
 parent_container_id TEXT NOT NULL,
 workspace_id TEXT NOT NULL,
 binding_hash TEXT NOT NULL,
 binding_epoch INTEGER NOT NULL,
 daemon_id TEXT NOT NULL,
 image_id TEXT NOT NULL,
 artifact_closure_sha256 TEXT NOT NULL,
 catalog_sha256 TEXT NOT NULL,
 deadline_at TEXT NOT NULL,
 deadline_ms INTEGER NOT NULL,
 created_at TEXT NOT NULL,
 phase TEXT NOT NULL CHECK(phase IN ('prepared','create_intent','created','start_intent','waiting','ready','material_spent','running','result','unknown','retired')),
 revision INTEGER NOT NULL CHECK(revision>=0),
 updated_ms INTEGER NOT NULL CHECK(updated_ms>=0),
 create_effect_hash TEXT,
 child_id TEXT UNIQUE,
 child_birth_hash TEXT UNIQUE,
 child_created_ms INTEGER,
 start_effect_hash TEXT,
 attach_identity_hash TEXT,
 child_start_hash TEXT,
 child_started_ms INTEGER,
 readiness_json TEXT,
 ready_observed_ms INTEGER,
 ready_expires_ms INTEGER,
 material_release_id TEXT UNIQUE,
 material_spent_ms INTEGER,
 material_readiness_json TEXT,
 material_ready_observed_ms INTEGER,
 material_ready_expires_ms INTEGER,
 result_json TEXT,
 unknown_code TEXT,
 unknown_ms INTEGER,
 cancel_requested_ms INTEGER,
 retirement_json TEXT,
 retired_ms INTEGER,
 CHECK(length(candidate_intent_hash)=64 AND candidate_intent_hash NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(spec_hash)=64 AND spec_hash NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(run_identity_hash)=64 AND run_identity_hash NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(selection_sha256)=64 AND selection_sha256 NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(parent_container_id)=64 AND parent_container_id NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(binding_hash)=64 AND binding_hash NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(artifact_closure_sha256)=64 AND artifact_closure_sha256 NOT GLOB '*[^0-9a-f]*'),
 CHECK(length(catalog_sha256)=64 AND catalog_sha256 NOT GLOB '*[^0-9a-f]*'),
 CHECK(create_effect_hash IS NULL OR (length(create_effect_hash)=64 AND create_effect_hash NOT GLOB '*[^0-9a-f]*')),
 CHECK(child_id IS NULL OR (length(child_id)=64 AND child_id NOT GLOB '*[^0-9a-f]*')),
 CHECK(child_birth_hash IS NULL OR (length(child_birth_hash)=64 AND child_birth_hash NOT GLOB '*[^0-9a-f]*')),
 CHECK(start_effect_hash IS NULL OR (length(start_effect_hash)=64 AND start_effect_hash NOT GLOB '*[^0-9a-f]*')),
 CHECK(attach_identity_hash IS NULL OR (length(attach_identity_hash)=64 AND attach_identity_hash NOT GLOB '*[^0-9a-f]*')),
 CHECK(child_start_hash IS NULL OR (length(child_start_hash)=64 AND child_start_hash NOT GLOB '*[^0-9a-f]*')),
 CHECK(binding_epoch>=0),
 CHECK(deadline_ms>0),
 CHECK(length(deadline_at)=24 AND deadline_at GLOB '????-??-??T??:??:??.???Z'),
 CHECK(deadline_ms=CAST(strftime('%s',deadline_at) AS INTEGER)*1000+CAST(substr(deadline_at,21,3) AS INTEGER)),
 CHECK(child_created_ms IS NULL OR child_created_ms>=0),
 CHECK(child_started_ms IS NULL OR child_started_ms>=0),
 CHECK(ready_observed_ms IS NULL OR ready_observed_ms>=0),
 CHECK(ready_expires_ms IS NULL OR ready_expires_ms>=0),
 CHECK(material_spent_ms IS NULL OR material_spent_ms>=0),
 CHECK(unknown_ms IS NULL OR unknown_ms>=0),
 CHECK(cancel_requested_ms IS NULL OR cancel_requested_ms>=0),
 CHECK(retired_ms IS NULL OR retired_ms>=0),
 CHECK((child_id IS NULL)=(child_birth_hash IS NULL) AND (child_id IS NULL)=(child_created_ms IS NULL)),
 CHECK((start_effect_hash IS NULL)=(attach_identity_hash IS NULL)),
 CHECK((child_start_hash IS NULL)=(child_started_ms IS NULL)),
 CHECK((readiness_json IS NULL)=(ready_observed_ms IS NULL) AND (readiness_json IS NULL)=(ready_expires_ms IS NULL)),
 CHECK((material_release_id IS NULL)=(material_spent_ms IS NULL) AND (material_release_id IS NULL)=(material_readiness_json IS NULL) AND (material_release_id IS NULL)=(material_ready_observed_ms IS NULL) AND (material_release_id IS NULL)=(material_ready_expires_ms IS NULL)),
 CHECK((unknown_code IS NULL)=(unknown_ms IS NULL)),
 CHECK((retirement_json IS NULL)=(retired_ms IS NULL)),
 CHECK(unknown_code IS NULL OR unknown_code IN ('create_ack_unknown','start_ack_unknown','attach_eof','material_ack_unknown','runtime_owner_unknown','candidate_result_unknown')),
 CHECK(child_id IS NULL OR create_effect_hash IS NOT NULL),
 CHECK(start_effect_hash IS NULL OR child_id IS NOT NULL),
 CHECK(child_start_hash IS NULL OR start_effect_hash IS NOT NULL),
 CHECK(readiness_json IS NULL OR child_start_hash IS NOT NULL),
 CHECK(material_release_id IS NULL OR readiness_json IS NOT NULL),
 CHECK(result_json IS NULL OR material_release_id IS NOT NULL),
 CHECK(unknown_ms IS NULL OR phase IN ('unknown','retired')),
 CHECK((phase='retired')=(retirement_json IS NOT NULL)),
 CHECK(phase!='prepared' OR (create_effect_hash IS NULL AND child_id IS NULL)),
 CHECK(phase!='create_intent' OR (create_effect_hash IS NOT NULL AND child_id IS NULL)),
 CHECK(phase!='created' OR (child_id IS NOT NULL AND start_effect_hash IS NULL)),
 CHECK(phase!='start_intent' OR (start_effect_hash IS NOT NULL AND child_start_hash IS NULL)),
 CHECK(phase!='waiting' OR (child_start_hash IS NOT NULL AND readiness_json IS NULL)),
 CHECK(phase!='ready' OR (readiness_json IS NOT NULL AND material_release_id IS NULL)),
 CHECK(phase NOT IN ('material_spent','running') OR (material_release_id IS NOT NULL AND result_json IS NULL)),
 CHECK(phase!='result' OR result_json IS NOT NULL),
 CHECK(phase!='unknown' OR unknown_ms IS NOT NULL),
 CHECK(material_release_id IS NULL OR length(material_release_id) BETWEEN 1 AND 128),
 CHECK(readiness_json IS NULL OR (length(CAST(readiness_json AS BLOB))<=16384 AND json_valid(readiness_json))),
 CHECK(result_json IS NULL OR (length(CAST(result_json AS BLOB))<=4096 AND json_valid(result_json))),
 CHECK(retirement_json IS NULL OR (length(CAST(retirement_json AS BLOB))<=8192 AND json_valid(retirement_json))),
 CHECK(ready_observed_ms IS NULL OR (ready_expires_ms>ready_observed_ms AND ready_expires_ms-ready_observed_ms<=5000 AND ready_expires_ms<=deadline_ms)),
 CHECK(material_spent_ms IS NULL OR material_spent_ms<=material_ready_expires_ms),
 CHECK(readiness_json IS NULL OR COALESCE((json_type(readiness_json,'$.schemaVersion')='integer' AND json_extract(readiness_json,'$.schemaVersion') IS 1 AND json_extract(readiness_json,'$.kind') IS 'original-candidate-ready-v1' AND json_extract(readiness_json,'$.runId') IS run_id AND json_extract(readiness_json,'$.attemptId') IS attempt_id AND json_extract(readiness_json,'$.candidateIntentHash') IS candidate_intent_hash AND json_extract(readiness_json,'$.specHash') IS spec_hash AND json_extract(readiness_json,'$.containerId') IS child_id AND json_extract(readiness_json,'$.childBirthHash') IS child_birth_hash AND json_extract(readiness_json,'$.childStartHash') IS child_start_hash AND json_extract(readiness_json,'$.daemonId') IS daemon_id AND json_extract(readiness_json,'$.imageId') IS image_id AND json_extract(readiness_json,'$.catalogSha256') IS catalog_sha256 AND json_extract(readiness_json,'$.artifactClosureSha256') IS artifact_closure_sha256 AND json_extract(readiness_json,'$.selectionSha256') IS selection_sha256 AND json_extract(readiness_json,'$.attachIdentityHash') IS attach_identity_hash AND json_extract(readiness_json,'$.trapAddress') IS '127.0.0.1:39261' AND json_extract(readiness_json,'$.proxyAddress') IS '127.0.0.1:39262' AND json_extract(readiness_json,'$.observedAt') IS ready_observed_ms AND json_extract(readiness_json,'$.expiresAt') IS ready_expires_ms AND json_extract(readiness_json,'$.networkMode')='none' AND json_type(readiness_json,'$.tty')='false' AND json_type(readiness_json,'$.pid')='integer' AND json_extract(readiness_json,'$.pid')>0),0)),
 CHECK(material_readiness_json IS NULL OR COALESCE((json_type(material_readiness_json,'$.schemaVersion')='integer' AND json_extract(material_readiness_json,'$.schemaVersion') IS 1 AND json_extract(material_readiness_json,'$.kind') IS 'original-candidate-ready-v1' AND json_extract(material_readiness_json,'$.runId') IS run_id AND json_extract(material_readiness_json,'$.attemptId') IS attempt_id AND json_extract(material_readiness_json,'$.candidateIntentHash') IS candidate_intent_hash AND json_extract(material_readiness_json,'$.specHash') IS spec_hash AND json_extract(material_readiness_json,'$.containerId') IS child_id AND json_extract(material_readiness_json,'$.childBirthHash') IS child_birth_hash AND json_extract(material_readiness_json,'$.childStartHash') IS child_start_hash AND json_extract(material_readiness_json,'$.daemonId') IS daemon_id AND json_extract(material_readiness_json,'$.imageId') IS image_id AND json_extract(material_readiness_json,'$.catalogSha256') IS catalog_sha256 AND json_extract(material_readiness_json,'$.artifactClosureSha256') IS artifact_closure_sha256 AND json_extract(material_readiness_json,'$.selectionSha256') IS selection_sha256 AND json_extract(material_readiness_json,'$.attachIdentityHash') IS attach_identity_hash AND json_extract(material_readiness_json,'$.trapAddress') IS '127.0.0.1:39261' AND json_extract(material_readiness_json,'$.proxyAddress') IS '127.0.0.1:39262' AND json_extract(material_readiness_json,'$.observedAt') IS material_ready_observed_ms AND json_extract(material_readiness_json,'$.expiresAt') IS material_ready_expires_ms AND json_extract(material_readiness_json,'$.networkMode')='none' AND json_type(material_readiness_json,'$.tty')='false' AND json_type(material_readiness_json,'$.pid')='integer' AND json_extract(material_readiness_json,'$.pid')>0),0)),
 CHECK(material_readiness_json IS NULL OR (json_valid(material_readiness_json) AND length(CAST(material_readiness_json AS BLOB))<=16384 AND material_ready_observed_ms>=ready_observed_ms AND material_ready_expires_ms>material_ready_observed_ms AND material_ready_expires_ms-material_ready_observed_ms<=5000 AND material_ready_expires_ms<=deadline_ms)),
 CHECK(result_json IS NULL OR COALESCE((json_type(result_json,'$.schemaVersion')='integer' AND json_extract(result_json,'$.schemaVersion') IS 1 AND json_extract(result_json,'$.kind') IS 'original-candidate-result-v1' AND json_extract(result_json,'$.runId') IS run_id AND json_extract(result_json,'$.attemptId') IS attempt_id AND json_extract(result_json,'$.candidateIntentHash') IS candidate_intent_hash AND json_extract(result_json,'$.specHash') IS spec_hash AND json_extract(result_json,'$.containerId') IS child_id AND json_extract(result_json,'$.childBirthHash') IS child_birth_hash AND json_extract(result_json,'$.childStartHash') IS child_start_hash AND json_extract(result_json,'$.materialReleaseId') IS material_release_id AND json_type(result_json,'$.exitCode')='integer' AND json_extract(result_json,'$.verification') IN ('response-verified','unverified','error') AND length(json_extract(result_json,'$.reportSha256'))=64 AND json_extract(result_json,'$.reportSha256') NOT GLOB '*[^0-9a-f]*'),0))
) STRICT;
CREATE TRIGGER candidate131_new_marker BEFORE INSERT ON job_run_managed_execution
WHEN NEW.purpose='candidate-inert-v1' AND (NEW.candidate_waiting_protocol IS NOT 'original-candidate-waiting-v1' OR NEW.phase!='prepared' OR NEW.effect_fence!='open-v1' OR NEW.original_container_id IS NOT NULL OR NEW.material_consumed_at IS NOT NULL OR NEW.credential_id IS NOT NULL OR NEW.result_json IS NOT NULL OR NEW.retirement_proof IS NOT NULL)
BEGIN SELECT RAISE(ABORT,'New candidate requires original waiting protocol'); END;
CREATE TRIGGER candidate131_base_no_update BEFORE UPDATE ON job_run_managed_execution
WHEN NEW.candidate_waiting_protocol IS NOT OLD.candidate_waiting_protocol OR OLD.candidate_waiting_protocol='original-candidate-waiting-v1'
BEGIN SELECT RAISE(ABORT,'Original candidate base admission is immutable'); END;
CREATE TRIGGER candidate131_base_no_delete BEFORE DELETE ON job_run_managed_execution WHEN OLD.purpose='candidate-inert-v1'
BEGIN SELECT RAISE(ABORT,'Original candidate admission is retained'); END;
CREATE TRIGGER candidate131_base_no_replace BEFORE INSERT ON job_run_managed_execution
WHEN EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE (e.purpose='candidate-inert-v1' OR NEW.purpose='candidate-inert-v1') AND (e.run_id=NEW.run_id OR e.attempt_id=NEW.attempt_id))
 OR (NEW.original_container_id IS NOT NULL AND EXISTS(SELECT 1 FROM job_run_candidate_lifecycle c WHERE c.child_id=NEW.original_container_id))
BEGIN SELECT RAISE(ABORT,'Original candidate admission cannot be replaced'); END;
CREATE TRIGGER candidate131_extension_initial BEFORE INSERT ON job_run_candidate_lifecycle
WHEN NEW.phase!='prepared' OR NEW.revision!=0 OR NEW.create_effect_hash IS NOT NULL OR NEW.child_id IS NOT NULL OR NEW.child_birth_hash IS NOT NULL OR NEW.child_created_ms IS NOT NULL OR NEW.start_effect_hash IS NOT NULL OR NEW.attach_identity_hash IS NOT NULL OR NEW.child_start_hash IS NOT NULL OR NEW.child_started_ms IS NOT NULL OR NEW.readiness_json IS NOT NULL OR NEW.ready_observed_ms IS NOT NULL OR NEW.ready_expires_ms IS NOT NULL OR NEW.material_release_id IS NOT NULL OR NEW.material_spent_ms IS NOT NULL OR NEW.result_json IS NOT NULL OR NEW.unknown_code IS NOT NULL OR NEW.unknown_ms IS NOT NULL OR NEW.cancel_requested_ms IS NOT NULL OR NEW.retirement_json IS NOT NULL OR NEW.retired_ms IS NOT NULL OR NEW.material_readiness_json IS NOT NULL OR NEW.material_ready_observed_ms IS NOT NULL OR NEW.material_ready_expires_ms IS NOT NULL OR NOT EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE e.run_id=NEW.run_id AND e.purpose='candidate-inert-v1' AND e.candidate_waiting_protocol='original-candidate-waiting-v1' AND e.phase='prepared' AND e.effect_fence='open-v1' AND NEW.run_id IS e.run_id AND NEW.attempt_id IS e.attempt_id AND NEW.candidate_intent_hash IS e.candidate_intent_hash AND NEW.spec_hash IS e.spec_hash AND NEW.run_identity_hash IS e.run_identity_hash AND NEW.organization_id IS e.organization_id AND NEW.owner_user_id IS e.owner_user_id AND NEW.project_id IS e.project_id AND NEW.job_id IS e.job_id AND NEW.runtime_id IS e.runtime_id AND NEW.parent_container_id IS e.parent_container_id AND NEW.workspace_id IS e.workspace_id AND NEW.binding_hash IS e.binding_hash AND NEW.binding_epoch IS e.binding_epoch AND NEW.daemon_id IS e.daemon_id AND NEW.image_id IS e.image_id AND NEW.deadline_at IS e.deadline_at AND NEW.created_at IS e.created_at AND NEW.selection_sha256 IS json_extract(e.admission_json,'$.selectionSha256') AND NEW.artifact_closure_sha256 IS json_extract(e.candidate_intent_json,'$.artifactClosureSha256') AND NEW.catalog_sha256 IS json_extract(e.candidate_intent_json,'$.canary.catalogSha256') AND NEW.deadline_ms IS CAST(strftime('%s',e.deadline_at) AS INTEGER)*1000+CAST(substr(e.deadline_at,21,3) AS INTEGER))
BEGIN SELECT RAISE(ABORT,'Original candidate atomic seed required'); END;
CREATE TRIGGER candidate131_extension_no_replace BEFORE INSERT ON job_run_candidate_lifecycle
WHEN EXISTS(SELECT 1 FROM job_run_candidate_lifecycle c WHERE c.run_id=NEW.run_id OR c.attempt_id=NEW.attempt_id OR c.candidate_intent_hash=NEW.candidate_intent_hash OR (NEW.child_id IS NOT NULL AND c.child_id=NEW.child_id) OR (NEW.child_birth_hash IS NOT NULL AND c.child_birth_hash=NEW.child_birth_hash))
BEGIN SELECT RAISE(ABORT,'Original candidate lifecycle cannot be replaced'); END;
CREATE TRIGGER candidate131_extension_no_delete BEFORE DELETE ON job_run_candidate_lifecycle BEGIN SELECT RAISE(ABORT,'Original candidate lifecycle is retained'); END;
CREATE TRIGGER candidate131_seed AFTER INSERT ON job_run_managed_execution WHEN NEW.candidate_waiting_protocol='original-candidate-waiting-v1'
BEGIN
 INSERT INTO job_run_candidate_lifecycle(run_id,attempt_id,candidate_intent_hash,spec_hash,run_identity_hash,selection_sha256,organization_id,owner_user_id,project_id,job_id,runtime_id,parent_container_id,workspace_id,binding_hash,binding_epoch,daemon_id,image_id,artifact_closure_sha256,catalog_sha256,deadline_at,deadline_ms,created_at,phase,revision,updated_ms) VALUES(NEW.run_id,NEW.attempt_id,NEW.candidate_intent_hash,NEW.spec_hash,NEW.run_identity_hash,json_extract(NEW.admission_json,'$.selectionSha256'),NEW.organization_id,NEW.owner_user_id,NEW.project_id,NEW.job_id,NEW.runtime_id,NEW.parent_container_id,NEW.workspace_id,NEW.binding_hash,NEW.binding_epoch,NEW.daemon_id,NEW.image_id,json_extract(NEW.candidate_intent_json,'$.artifactClosureSha256'),json_extract(NEW.candidate_intent_json,'$.canary.catalogSha256'),NEW.deadline_at,CAST(strftime('%s',NEW.deadline_at) AS INTEGER)*1000+CAST(substr(NEW.deadline_at,21,3) AS INTEGER),NEW.created_at,'prepared',0,CAST(strftime('%s',NEW.created_at) AS INTEGER)*1000+CAST(substr(NEW.created_at,21,3) AS INTEGER));
END;
CREATE TRIGGER candidate131_transition BEFORE UPDATE ON job_run_candidate_lifecycle
WHEN OLD.phase='retired' OR NEW.revision!=OLD.revision+1 OR NEW.updated_ms<OLD.updated_ms
 OR NEW.run_id IS NOT OLD.run_id OR NEW.attempt_id IS NOT OLD.attempt_id OR NEW.candidate_intent_hash IS NOT OLD.candidate_intent_hash OR NEW.spec_hash IS NOT OLD.spec_hash OR NEW.run_identity_hash IS NOT OLD.run_identity_hash OR NEW.selection_sha256 IS NOT OLD.selection_sha256 OR NEW.organization_id IS NOT OLD.organization_id OR NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.project_id IS NOT OLD.project_id OR NEW.job_id IS NOT OLD.job_id OR NEW.runtime_id IS NOT OLD.runtime_id OR NEW.parent_container_id IS NOT OLD.parent_container_id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.binding_hash IS NOT OLD.binding_hash OR NEW.binding_epoch IS NOT OLD.binding_epoch OR NEW.daemon_id IS NOT OLD.daemon_id OR NEW.image_id IS NOT OLD.image_id OR NEW.artifact_closure_sha256 IS NOT OLD.artifact_closure_sha256 OR NEW.catalog_sha256 IS NOT OLD.catalog_sha256 OR NEW.deadline_at IS NOT OLD.deadline_at OR NEW.deadline_ms IS NOT OLD.deadline_ms OR NEW.created_at IS NOT OLD.created_at
 OR (OLD.create_effect_hash IS NOT NULL AND NEW.create_effect_hash IS NOT OLD.create_effect_hash) OR (OLD.child_id IS NOT NULL AND NEW.child_id IS NOT OLD.child_id) OR (OLD.child_birth_hash IS NOT NULL AND NEW.child_birth_hash IS NOT OLD.child_birth_hash) OR (OLD.child_created_ms IS NOT NULL AND NEW.child_created_ms IS NOT OLD.child_created_ms) OR (OLD.start_effect_hash IS NOT NULL AND NEW.start_effect_hash IS NOT OLD.start_effect_hash) OR (OLD.attach_identity_hash IS NOT NULL AND NEW.attach_identity_hash IS NOT OLD.attach_identity_hash) OR (OLD.child_start_hash IS NOT NULL AND NEW.child_start_hash IS NOT OLD.child_start_hash) OR (OLD.child_started_ms IS NOT NULL AND NEW.child_started_ms IS NOT OLD.child_started_ms) OR (OLD.readiness_json IS NOT NULL AND NEW.readiness_json IS NOT OLD.readiness_json) OR (OLD.ready_observed_ms IS NOT NULL AND NEW.ready_observed_ms IS NOT OLD.ready_observed_ms) OR (OLD.ready_expires_ms IS NOT NULL AND NEW.ready_expires_ms IS NOT OLD.ready_expires_ms) OR (OLD.material_release_id IS NOT NULL AND NEW.material_release_id IS NOT OLD.material_release_id) OR (OLD.material_spent_ms IS NOT NULL AND NEW.material_spent_ms IS NOT OLD.material_spent_ms) OR (OLD.result_json IS NOT NULL AND NEW.result_json IS NOT OLD.result_json) OR (OLD.unknown_code IS NOT NULL AND NEW.unknown_code IS NOT OLD.unknown_code) OR (OLD.unknown_ms IS NOT NULL AND NEW.unknown_ms IS NOT OLD.unknown_ms) OR (OLD.cancel_requested_ms IS NOT NULL AND NEW.cancel_requested_ms IS NOT OLD.cancel_requested_ms) OR (OLD.retirement_json IS NOT NULL AND NEW.retirement_json IS NOT OLD.retirement_json) OR (OLD.retired_ms IS NOT NULL AND NEW.retired_ms IS NOT OLD.retired_ms) OR (OLD.material_readiness_json IS NOT NULL AND NEW.material_readiness_json IS NOT OLD.material_readiness_json) OR (OLD.material_ready_observed_ms IS NOT NULL AND NEW.material_ready_observed_ms IS NOT OLD.material_ready_observed_ms) OR (OLD.material_ready_expires_ms IS NOT NULL AND NEW.material_ready_expires_ms IS NOT OLD.material_ready_expires_ms)
 OR COALESCE(((OLD.phase='prepared' AND NEW.phase='create_intent' AND OLD.cancel_requested_ms IS NULL AND NEW.updated_ms<=OLD.deadline_ms AND NEW.child_id IS OLD.child_id AND NEW.child_birth_hash IS OLD.child_birth_hash AND NEW.child_created_ms IS OLD.child_created_ms AND NEW.start_effect_hash IS OLD.start_effect_hash AND NEW.attach_identity_hash IS OLD.attach_identity_hash AND NEW.child_start_hash IS OLD.child_start_hash AND NEW.child_started_ms IS OLD.child_started_ms AND NEW.readiness_json IS OLD.readiness_json AND NEW.ready_observed_ms IS OLD.ready_observed_ms AND NEW.ready_expires_ms IS OLD.ready_expires_ms AND NEW.material_release_id IS OLD.material_release_id AND NEW.material_spent_ms IS OLD.material_spent_ms AND NEW.result_json IS OLD.result_json AND NEW.unknown_code IS OLD.unknown_code AND NEW.unknown_ms IS OLD.unknown_ms AND NEW.cancel_requested_ms IS OLD.cancel_requested_ms AND NEW.retirement_json IS OLD.retirement_json AND NEW.retired_ms IS OLD.retired_ms AND NEW.material_readiness_json IS OLD.material_readiness_json AND NEW.material_ready_observed_ms IS OLD.material_ready_observed_ms AND NEW.material_ready_expires_ms IS OLD.material_ready_expires_ms)
