CREATE TRIGGER candidate131_child_no_adoption BEFORE UPDATE ON job_run_candidate_lifecycle
WHEN OLD.child_id IS NULL AND NEW.child_id IS NOT NULL AND EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE e.original_container_id=NEW.child_id)
BEGIN SELECT RAISE(ABORT,'Original candidate cannot adopt another execution child'); END;
CREATE TRIGGER candidate131_run_no_delete BEFORE DELETE ON job_runs WHEN EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE e.run_id=OLD.id AND e.purpose='candidate-inert-v1') BEGIN SELECT RAISE(ABORT,'Original candidate Run is retained'); END;
CREATE TRIGGER candidate131_run_no_replace BEFORE INSERT ON job_runs WHEN EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE e.run_id=NEW.id AND e.purpose='candidate-inert-v1') BEGIN SELECT RAISE(ABORT,'Original candidate Run cannot be replaced'); END;
CREATE TRIGGER candidate131_run_terminal_guard BEFORE UPDATE ON job_runs
WHEN EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE e.run_id=OLD.id AND e.candidate_waiting_protocol='original-candidate-waiting-v1') AND
 ((OLD.status IN ('success','failed','timeout','cancelled') AND (NEW.status IS NOT OLD.status OR NEW.finished_at IS NOT OLD.finished_at))
 OR (NEW.status IN ('success','failed','timeout','cancelled') AND NEW.status IS NOT OLD.status AND NOT EXISTS(SELECT 1 FROM job_run_candidate_lifecycle c WHERE c.run_id=OLD.id AND c.phase='retired' AND c.retirement_json IS NOT NULL AND (NEW.status!='success' OR (json_extract(c.result_json,'$.verification')='response-verified' AND json_extract(c.result_json,'$.exitCode')=0 AND json_extract(c.retirement_json,'$.exitCode')=0)))))
BEGIN SELECT RAISE(ABORT,'Candidate requires original physical retirement before terminal outcome'); END;
-- Existing production credential/material guards intentionally remain unchanged.
-- Actual candidate credential/frame constructors and HTTP authorization are closed Root gates.

CREATE TRIGGER candidate131_run_identity BEFORE UPDATE ON job_runs
WHEN EXISTS(SELECT 1 FROM job_run_managed_execution e WHERE e.run_id=OLD.id AND e.purpose='candidate-inert-v1') AND (NEW.id IS NOT OLD.id OR NEW.job_id IS NOT OLD.job_id OR NEW.project_id IS NOT OLD.project_id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.effective_service_principal_id IS NOT OLD.effective_service_principal_id OR NEW.job_revision IS NOT OLD.job_revision OR NEW.schedule_revision IS NOT OLD.schedule_revision OR NEW.authorization_revision IS NOT OLD.authorization_revision OR NEW.trigger IS NOT OLD.trigger OR NEW.scheduled_for IS NOT OLD.scheduled_for OR NEW.created_at IS NOT OLD.created_at)
BEGIN SELECT RAISE(ABORT,'Original candidate Run identity is immutable'); END;

CREATE TRIGGER candidate131_exact_evidence BEFORE UPDATE ON job_run_candidate_lifecycle
WHEN (NEW.readiness_json IS NOT NULL AND ((SELECT count(*) FROM json_each(NEW.readiness_json))!=22 OR (SELECT count(DISTINCT key) FROM json_each(NEW.readiness_json))!=22 OR EXISTS(SELECT 1 FROM json_each(NEW.readiness_json) WHERE key NOT IN ('schemaVersion','kind','runId','attemptId','candidateIntentHash','specHash','containerId','childBirthHash','childStartHash','daemonId','imageId','catalogSha256','artifactClosureSha256','selectionSha256','attachIdentityHash','trapAddress','proxyAddress','pid','networkMode','tty','observedAt','expiresAt'))))
 OR (NEW.material_readiness_json IS NOT NULL AND ((SELECT count(*) FROM json_each(NEW.material_readiness_json))!=22 OR (SELECT count(DISTINCT key) FROM json_each(NEW.material_readiness_json))!=22 OR EXISTS(SELECT 1 FROM json_each(NEW.material_readiness_json) WHERE key NOT IN ('schemaVersion','kind','runId','attemptId','candidateIntentHash','specHash','containerId','childBirthHash','childStartHash','daemonId','imageId','catalogSha256','artifactClosureSha256','selectionSha256','attachIdentityHash','trapAddress','proxyAddress','pid','networkMode','tty','observedAt','expiresAt'))))
 OR (NEW.result_json IS NOT NULL AND ((SELECT count(*) FROM json_each(NEW.result_json))!=13 OR (SELECT count(DISTINCT key) FROM json_each(NEW.result_json))!=13 OR EXISTS(SELECT 1 FROM json_each(NEW.result_json) WHERE key NOT IN ('schemaVersion','kind','runId','attemptId','candidateIntentHash','specHash','containerId','childBirthHash','childStartHash','materialReleaseId','exitCode','verification','reportSha256'))))
 OR (NEW.retirement_json IS NOT NULL AND ((json_extract(NEW.retirement_json,'$.kind')='original-candidate-no-create-v1' AND ((SELECT count(*) FROM json_each(NEW.retirement_json))!=9 OR (SELECT count(DISTINCT key) FROM json_each(NEW.retirement_json))!=9 OR EXISTS(SELECT 1 FROM json_each(NEW.retirement_json) WHERE key NOT IN ('schemaVersion','kind','runId','attemptId','candidateIntentHash','specHash','createEffectHash','originalNotSentSha256','retiredAtMs')))) OR (json_extract(NEW.retirement_json,'$.kind')!='original-candidate-no-create-v1' AND ((SELECT count(*) FROM json_each(NEW.retirement_json))!=14 OR (SELECT count(DISTINCT key) FROM json_each(NEW.retirement_json))!=14 OR EXISTS(SELECT 1 FROM json_each(NEW.retirement_json) WHERE key NOT IN ('schemaVersion','kind','runId','attemptId','candidateIntentHash','specHash','containerId','childBirthHash','childStartHash','daemonId','exitCode','waitJoinSha256','eofSha256','retiredAtMs'))))))
BEGIN SELECT RAISE(ABORT,'Original candidate evidence has an exact bounded shape'); END;
